 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    # The two aligned markers define the horizontal spine.
    row_counts = {}
    for r, c in points:
        row_counts[r] = row_counts.get(r, 0) + 1
    spine = max((r for r, n in row_counts.items() if n >= 2), key=lambda r: row_counts[r])
    spine_cols = [c for r, c in points if r == spine]
    lo, hi = min(spine_cols), max(spine_cols)
    for c in range(lo + 1, hi):
        if out[spine][c] == 0:
            out[spine][c] = 3
    for r, c in points:
        if r != spine:
            step = 1 if r < spine else -1
            rr = r + step
            while rr != spine:
                if out[rr][c] == 0:
                    out[rr][c] = 3
                rr += step
    return out
